-- 0014 - Tabelas de custo dos fornecedores (Gabriel, 27/11/2026).
-- Gerado a partir das tabelas enviadas: Armazém das Cortinas (29/05/2026), Casa do Cortineiro (13/05/2026)
-- e Slim (persianas, peças e motorização). Valores = CUSTO; venda = custo x (1 + markup da categoria).
--
-- 1. Inativa todos os PRODUTOS cadastrados até agora (serviços continuam ativos). A lista fica em
--    produtos_inativados_0014 para dar para voltar atrás, se precisar.
-- 2. Cria os fornecedores e as subcategorias Persidress (Persianas) e Trilhos Motorizados (Acessórios Cortinas).
-- 3. Cadastra os produtos com SKU = 3 letras do fornecedor + tipo + sequência (ARMTEC-0001, CORTEC-0001,
--    SLIPER-0001...). TEC tecido, TRI trilho/varão, ACE acessório de cortina, PER persiana,
--    ACP peça de persiana, MOT motorização. SKU que já existir não é alterado.
-- 4. Trilhos e varões: preço por barra de 1 a 6 m = preço do metro x tamanho.
-- 5. Prazo de entrega padrão: 12 dias úteis.

CREATE TABLE produtos_inativados_0014 (produto_id UUID PRIMARY KEY);
  SELECT p.id FROM produtos p
  WHERE p.ativo IS DISTINCT FROM FALSE
    AND p.categoria_id NOT IN (SELECT id FROM categorias_produto WHERE id = 11 OR pai_id = 11);
UPDATE produtos SET ativo = FALSE, atualizado_em = NOW() WHERE id IN (SELECT produto_id FROM produtos_inativados_0014);

ON CONFLICT DO NOTHING;

SELECT f.nome, f.cat, f.prazo FROM (VALUES
  ('Armazém das Cortinas', 'TECIDO', 12), ('Casa do Cortineiro', 'TECIDO', 12), ('Slim', 'PERSIANA', 12)
) AS f(nome, cat, prazo)
WHERE NOT EXISTS (SELECT 1 FROM fornecedores x WHERE f_busca(x.nome_fantasia) = f_busca(f.nome));

-- Markup efetivo da categoria (sobe na árvore até achar; padrão 100%).
CREATE FUNCTION pg_temp.markup_efetivo(cat INT) RETURNS NUMERIC LANGUAGE sql STABLE AS $$
  WITH RECURSIVE sobe AS (
    SELECT id, pai_id, markup_pct, 0 AS nivel FROM categorias_produto WHERE id = cat
    UNION ALL
    SELECT c.id, c.pai_id, c.markup_pct, s.nivel + 1 FROM categorias_produto c JOIN sobe s ON c.id = s.pai_id
  )
  SELECT COALESCE((SELECT markup_pct FROM sobe WHERE markup_pct IS NOT NULL ORDER BY nivel LIMIT 1), 100)
$$;

CREATE TEMP TABLE novos_0014 (sku VARCHAR(30), categoria_id INT, fornecedor VARCHAR(140), nome VARCHAR(160),
  cor VARCHAR(80), unidade unidade_medida_enum, custo NUMERIC(12,4), metadata JSONB) ON COMMIT DROP;

SELECT n.sku, n.categoria_id,
       (SELECT f.id FROM fornecedores f WHERE f_busca(f.nome_fantasia) = f_busca(n.fornecedor) ORDER BY f.ativo DESC NULLS LAST LIMIT 1),
       n.nome, n.cor, n.unidade, n.custo,
       ROUND(n.custo * (1 + pg_temp.markup_efetivo(n.categoria_id) / 100), 2), n.metadata, TRUE
FROM novos_0014 n
ON CONFLICT (sku) DO NOTHING;

-- Trilhos e varões: preço da barra = metro x tamanho (o ADMIN pode trocar por barra na tela do produto).
SELECT p.id, t.tam, ROUND(n.custo * t.tam, 2), ROUND(n.custo * t.tam * (1 + pg_temp.markup_efetivo(n.categoria_id) / 100), 2)
FROM novos_0014 n
JOIN produtos p ON p.sku = n.sku
CROSS JOIN generate_series(1, 6) AS t(tam)
WHERE n.categoria_id = 2
ON CONFLICT DO NOTHING;

-- Prazo de entrega padrão para todos: 12 dias úteis (Gabriel, 27/11/2026).
SELECT id, 'PRAZO_ENTREGA_DIAS_UTEIS', 12, CURRENT_DATE FROM lojas
ON CONFLICT (loja_id, chave, vigente_desde) DO UPDATE SET valor = 12;
UPDATE fornecedores SET prazo_entrega_dias = 12 WHERE ativo IS DISTINCT FROM FALSE;
